class Solution {
    vector<int> parent;
    vector<long long> sum;
    int find(int x){
        return parent[x]==x?x:parent[x]=find(parent[x]);
    }
    void unite(int a,int b){
        a=find(a);
        b=find(b);
        if(a!=b){
            parent[b]=a;
            sum[a]+=sum[b];
        }
    }
    public:vector<long long> maximumSegmentSum(vector<int>& nums,vector<int>& removeQueries){
        int n=nums.size();
        parent.resize(n);
        sum.resize(n);
        vector<bool> active(n);
        vector<long long> answer(n);
        long long maximum=0;
        for(int i=n-1;i>=0;--i){
            answer[i]=maximum;
            int index=removeQueries[i];
            parent[index]=index;
            sum[index]=nums[index];
            active[index]=true;
            if(index&&active[index-1])unite(index,index-1);
            if(index+1<n&&active[index+1])unite(index,index+1);
            maximum=max(maximum,sum[find(index)]);
        }
        return answer;
    }
};
